CREATE DATABASE customer_behavior;

USE customer_behavior;


-- Q1. What is the total revenue generated by male vs. female customers?
select
	gender,
	SUM(purchase_amount) as revenue
from
	customer
group by gender;

-- Q2. Which customers used a discount but still spent more than the average purchase amount?
select customer_id,discount_applied,purchase_amount
from customer
where discount_applied = 'Yes' and purchase_amount > (select avg(purchase_amount) from customer);

-- Q3. Which are the top 5 products with the highest average review rating?
select top 5 item_purchased, ROUND(AVG(review_rating),2) as avg_rating
from customer
group by item_purchased
order by avg_rating desc;

-- Q4. Compare the average Purchase Amounts between Standard and Express Shipping?
select shipping_type, ROUND(AVG(purchase_amount),2) as revenue
from customer
group by shipping_type
having shipping_type in('standard','express');

-- Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers?
select subscription_status,COUNT(customer_id) Total_customers, ROUND(AVG(purchase_amount),2) Avg_spend, ROUND(SUM(purchase_amount),2) Total_revenue
from customer
group by subscription_status
order by Total_revenue desc;

-- Q6. Which 5 products have the highest percentage of purchases with discounts applied?
select TOP 5 item_purchased, ROUND(100*SUM(CASE WHEN discount_applied = 'yes' THEN 1 ELSE 0 END)/COUNT(*),2) discount_rate
from customer
group by item_purchased
order by discount_rate desc;

-- Q7. Segment customers into New, Returning, and Loyal based on their total number of previous purchases, and show the count of each segment?
with customer_type as (
	select customer_id,previous_purchases,
		CASE
			WHEN previous_purchases ='1' THEN 'New'
			WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
			ELSE 'Loyal'
		END AS customer_segment
	from customer
)
select customer_segment, COUNT(*) 'Number of customers'
from customer_type
group by customer_segment
order by [Number of customers] desc;

-- Q8. What are the top 3 most purchased products within each category?
with item_counts as (
	select category,item_purchased, COUNT(*) order_counts,ROW_NUMBER() OVER(PARTITION BY category ORDER BY COUNT(*) DESC) as item_rank
	from customer
	group by item_purchased,category
)
select item_rank, category, item_purchased, order_counts
from item_counts
where item_rank <=3;

-- Q9. Are customers who are repeat buyers ( more than 5 previous purchases ) also likely to subscribe?
select subscription_status,COUNT(customer_id) as repeat_buyers
from customer
where previous_purchases > 5
group by subscription_status
order by repeat_buyers desc;

-- Q10. What is the revenue contribution of each age_group?
select age_group,SUM(purchase_amount) as Total_revenue
from customer
group by age_group
order by Total_revenue desc;